def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # A long uniform run followed by a shorter contrasting suffix marks
        # the suffix; recolor it to 1.
        if len(row) < 2:
            continue
        first = row[0]
        k = 1
        while k < len(row) and row[k] == first:
            k += 1
        if 0 < k < len(row) and all(x == row[k] for x in row[k:]) and k >= len(row) // 2:
            out[r][k:] = [1] * (len(row) - k)
    return out

def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # If a contiguous non-background run reaches the right side,
        # recolor the background tail after it.
        end = len(row)
        while end > 0 and row[end - 1] == row[0]:
            end -= 1
        # General rule: identify last non-background cell and its run.
        bg = max(set(row), key=row.count)
        i = len(row) - 1
        while i >= 0 and row[i] == bg:
            i -= 1
        if i >= 0 and i < len(row) - 1:
            c = row[i]
            j = i
            while j >= 0 and row[j] == c:
                j -= 1
            if i - j >= 3:
                out[r][i+1:] = [1] * (len(row)-i-1)
    return out

