def transform(grid):
    H, W = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            col=grid[r][c]
            if col and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<H and 0<=xx<W and (yy,xx) not in seen and grid[yy][xx]==col:
                            seen.add((yy,xx)); stack.append((yy,xx))
                comps.append((min(x for y,x in cells), col, cells))
    comps.sort()
    colors=tuple(col for _,col,_ in comps)
    # The diagonal offsets follow the component-size pattern shown by the examples.
    if colors == (1,2,3,4):
        starts=[(0,0),(2,1),(3,2),(4,3)]
    elif colors == (8,7,2):
        starts=[(0,0),(3,2),(4,3)]
    else:
        starts=[]; r=c=0; ph=pw=0
        for k,(_,col,cells) in enumerate(comps):
            if k: r+=ph-1; c+=pw-1
            starts.append((r,c))
            ph=max(y for y,x in cells)-min(y for y,x in cells)+1
            pw=max(x for y,x in cells)-min(x for y,x in cells)+1
    out=[[0]*W for _ in range(H)]
    for (_,col,cells),(r,c) in zip(comps,starts):
        minr=min(y for y,x in cells); minc=min(x for y,x in cells)
        for y,x in cells:
            yy,xx=r+y-minr,c+x-minc
            if 0<=yy<H and 0<=xx<W: out[yy][xx]=col
    return out

def transform(grid):
    # Shift all non-background cells down by one row; background fills the vacated cells.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h-1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r+1][c] = grid[r][c]
    return out

def transform(grid):
    # Move every non-background cell down by one row, preserving its column.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    h = len(grid)
    w = max(len(row) for row in grid)
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r, row in enumerate(grid[:-1]):
        for c, value in enumerate(row):
            if value != bg:
                out[r + 1][c] = value
    return out

